import pandas as pd, numpy as np, statsmodels.api as sm
from scipy.stats import f as fdist
df=pd.read_csv('data.csv'); D=df.D.values; y=df.dY.values
def covmat(d):
    X=pd.get_dummies(d[['region','tier']],drop_first=True).astype(float)
    X['hist']=d.log_hist_days; X['hist2']=d.log_hist_days**2; X['pregmv']=d.log_pre_gmv
    X['orders']=d.orders; X['cat']=d.cat_share; X['ten']=np.log1p(d.tenure); X['plac']=d.dY_placebo
    return np.column_stack([np.ones(len(d)),X.values])
def analyze(mask,name):
    d=df[mask]; Dd=d.D.values; yy=d.dY.values; C=covmat(d); nn=len(d)
    if nn<400: print(f"{name}: n={nn} 样本过小"); return
    knots=np.arange(6,19,1.0)
    B=np.column_stack([Dd]+[np.maximum(Dd-k,0) for k in knots])
    r=sm.OLS(yy,np.column_stack([B,C])).fit(cov_type='HC1'); P=r.params[:B.shape[1]]; V=r.cov_params()[:B.shape[1],:B.shape[1]]
    def sl(a,b):
        v=lambda x: np.concatenate([[1],[1.0*(x>k) for k in knots]])
        dv=v(b)-v(a); return dv@P, np.sqrt(dv@V@dv)
    s1,e1=sl(7.5,8.5); s2,e2=sl(10.5,11.5); s3,e3=sl(14.5,15.5)
    # 最佳折点
    best=(None,np.inf)
    for k in knots:
        M=np.column_stack([Dd,np.maximum(Dd-k,0),C]); rr=sm.OLS(yy,M).fit(); s=np.sum(rr.resid**2)
        if s<best[1]: best=(k,s)
    print(f"{name:26s} n={nn:5d} | 斜率@8={s1:+.3f}({s1/e1:+.1f}σ) @11={s2:+.3f}({s2/e2:+.1f}σ) @15={s3:+.3f}({s3/e3:+.1f}σ) | 最佳折点={best[0]:.0f}")
analyze(pd.Series(True,index=df.index),"全体")
for t in [0,1,2,3]: analyze(df.tier==t,f"tier={t}")
for r in range(5): analyze(df.region==r,f"region={r}")
for q,lab in enumerate(['低','中低','中高','高']): analyze(pd.qcut(df.log_hist_days,4,labels=False)==q,f"历史妥投天数{lab}四分位")
for q in range(3): analyze(pd.qcut(df.log_pre_gmv,3,labels=False)==q,f"pre_GMV分位{q+1}")
analyze(df.orders>=3,"高频用户(orders>=3)")
analyze(df.orders<3,"低频用户(orders<3)")
